// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address creator;
    address attacker = address(0x1234);

    function setUp() public {
        c = new C();
        creator = address(this);
    }

    function testFuzz_property(address caller, uint256 amount) public {
        // Ensure caller is not the creator
        vm.assume(caller != creator);
        vm.assume(caller != address(0));

        // Bound amount to avoid overflow
        amount = bound(amount, 1, 100 ether);

        // Give caller some ether
        vm.deal(caller, amount);

        // Caller deposits funds
        vm.prank(caller);
        c.deposit{value: amount}();

        uint256 balanceBefore = address(c).balance;

        // caller tries to call migrateTo
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("migrateTo(address)", address(0xdead)));

        uint256 balanceAfter = address(c).balance;

        // Rule: A non-creator calling migrateTo should NOT change the contract balance
        assertTrue(balanceBefore == balanceAfter);
    }
}

